import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { parsePo, serializePo, writeCatalog } from './tools/i18n-engine/src/po.ts';

const root = process.cwd();
const source = readFileSync(join(root, 'docs/guide/cli.md'), 'utf8');
const currentIntro = '`@pantoken/cli` provides `pantoken generate <target>`, which writes token source into a target repo,\nand `pantoken add <item>`, a convenience wrapper around the shadcn registry. Reach for `generate`\nwhen a platform needs generated code rather than a runtime dependency — native apps, CMS themes,\nand static-site generators.';
const registrySection = 'For a project configured with shadcn, this delegates to `shadcn add @pantoken/<item>` and registers\nthe indexed namespace when necessary:\n\n```sh\nnpx pantoken add button\n```\n\nUse the official shadcn `list`, `search`, and `view` commands for discovery. Registry items install\nPantoken CSS styles and metadata, not React components.';

const show = (path) => execFileSync('git', ['show', `main:${path}`], { encoding: 'utf8' });
const insertAfterGenerateExample = (content) => {
  const marker = '```sh\nnpx pantoken generate <target> --out <dir> [--theme <name>] [--icons a,b,c]\n```';
  if (!content.includes(marker)) throw new Error('Missing generate example marker');
  return content.replace(marker, `${marker}\n\n${registrySection}`);
};

const locales = readdirSync(join(root, 'l10n'), { withFileTypes: true })
  .filter((entry) => entry.isDirectory() && entry.name !== 'en')
  .map((entry) => entry.name);

for (const locale of locales) {
  const path = `docs/${locale}/guide/cli.md`;
  const oldLocalized = existsSync(join(root, path)) ? show(path) : source;
  const localized = insertAfterGenerateExample(oldLocalized);
  const outPath = join(root, path);
  mkdirSync(dirname(outPath), { recursive: true });
  writeFileSync(outPath, localized);

  const poPath = join(root, 'l10n', locale, 'docs.guides.po');
  const entries = parsePo(readFileSync(poPath, 'utf8'));
  const entry = entries.find((item) => !item.obsolete && item.references.includes('guide/cli.md'));
  if (!entry) throw new Error(`Missing guide/cli.md entry for ${locale}`);
  entry.msgid = source;
  entry.msgstr = localized;
  entry.fuzzy = false;
  entry.flags = entry.flags.filter((flag) => flag !== 'fuzzy');
  writeCatalog(poPath, serializePo(entries));
}
